std::vector<std::string> Lines(const std::string& s) {
    std::vector<std::string> out;
    size_t b = 0;
    while (b < s.size()) {
        size_t e = s.find('\n', b);
        if (e == std::string::npos) e = s.size();
        out.push_back(s.substr(b, e - b));
        b = e + 1;
    }
    return out;
}

std::string Join(const std::vector<std::string>& lines) {
    std::string s;
    for (const std::string& l : lines) s += l + "\n";
    return s;
}

std::string ReplaceFirst(std::string s, const std::string& from, const std::string& to) {
    size_t p = s.find(from);
    REQUIRE_MESSAGE(p != std::string::npos, "missing '" << from << "'");
    return s.replace(p, from.size(), to);
}

// first match only
std::string ReplaceInBlock(const std::string& text, const std::string& id, const std::string& from,
                           const std::string& to) {
    ParsedFile pf;
    REQUIRE(ParseGenerated(text, pf, nullptr));
    const Block* b = pf.Find(Block::Kind::Begin, id);
    REQUIRE_MESSAGE(b, "no block " << id);
    std::vector<std::string> lines = Lines(text);
    for (int ln = b->line_begin; ln < b->line_end; ++ln) {
        std::string& l = lines[(size_t)ln];
        size_t p = l.find(from);
        if (p == std::string::npos) continue;
        l.replace(p, from.size(), to);
        return Join(lines);
    }
    FAIL("'" << from << "' not found in block " << id);
    return text;
}

std::string WrapBlock(const std::string& text, const std::string& id, const std::string& cond) {
    ParsedFile pf;
    REQUIRE(ParseGenerated(text, pf, nullptr));
    const Block* b = pf.Find(Block::Kind::Begin, id);
    REQUIRE_MESSAGE(b, "no block " << id);
    std::vector<std::string> lines = Lines(text);
    lines.insert(lines.begin() + (b->line_end - 1), "        }");
    lines.insert(lines.begin() + b->line_begin, "        if (" + cond + ") {");
    return Join(lines);
}

std::string FillSlot(const std::string& text, const std::string& slot, const std::string& line) {
    return ReplaceFirst(text, "// @imb:user id=" + slot + "\n",
                        "// @imb:user id=" + slot + "\n" + line + "\n");
}

int LineOf(const std::string& text, const std::string& needle) {
    std::vector<std::string> lines = Lines(text);
    for (size_t i = 0; i < lines.size(); ++i)
        if (lines[i].find(needle) != std::string::npos) return (int)i + 1;
    return -1;
}

bool Has(const std::vector<std::string>& v, const std::string& s) {
    return std::find(v.begin(), v.end(), s) != v.end();
}

bool Contains(const std::string& hay, const std::string& needle) {
    return hay.find(needle) != std::string::npos;
}

std::vector<std::string> FlagNames(const Node& n, const char* prop = "flags") {
    std::vector<std::string> out;
    const PropValue* p = n.Prop(prop);
    if (!p) return out;
    for (const Json& j : p->raw.arr) out.push_back(j.AsString());
    return out;
}

codegen::LiteralRef Ref(const char* node, const char* prop, int block_index, const char* file) {
    codegen::LiteralRef r;
    r.node_id = node;
    r.prop = prop;
    r.block_token_index = block_index;
    r.token_index = -1;
    r.file = file;
    return r;
}

size_t IndexOf(const std::vector<Token>& t, const std::string& text) {
    for (size_t i = 0; i < t.size(); ++i)
        if (t[i].text == text) return i;
    FAIL("token '" << text << "' not found");
    return 0;
}

