    user = ReplaceInBlock(user, "window", "ImGuiWindowFlags_NoCollapse",
                          "ImGuiWindowFlags_NoCollapse | ImGuiWindowFlags_NoMove");
    user = ReplaceInBlock(user, "window", "\"Demo\"", "\"Demo!\\n\"");
    user = ReplaceInBlock(user, "window", "520 * imb_s", "600 * imb_s");
    user = ReplaceInBlock(user, "window", "ImGuiCond_FirstUseEver", "ImGuiCond_Once");
    user = ReplaceInBlock(user, "col", "ImVec4(0.18f, 0.8f, 0.44f, 1.0f)", "ImVec4(1, 0, 0, 0.5f)");
