    CHECK(FlagNames(*sl) == std::vector<std::string>{"AlwaysClamp"});
    CHECK(sl->Prop("label")->raw.AsString() == "Speed");
    CHECK(FlagNames(*win) == std::vector<std::string>{"NoCollapse", "NoMove"});
    CHECK(win->Prop("title")->raw.AsString() == "Demo!\n");
